<?php
class Dashboard extends Model { public function metrics():array{return $this->db->query("SELECT (SELECT COUNT(*) FROM clientes WHERE estado=1) clientes,(SELECT COUNT(*) FROM equipos) equipos,(SELECT COUNT(*) FROM ordenes_servicio o JOIN estados_orden e ON e.id_estado=o.id_estado WHERE e.nombre_estado='Pendiente') pendientes,(SELECT COUNT(*) FROM ordenes_servicio o JOIN estados_orden e ON e.id_estado=o.id_estado WHERE e.nombre_estado='En proceso') proceso,(SELECT COUNT(*) FROM ordenes_servicio o JOIN estados_orden e ON e.id_estado=o.id_estado WHERE e.nombre_estado='Cerrada') cerradas,(SELECT COUNT(*) FROM tecnicos WHERE estado=1) tecnicos,(SELECT COUNT(*) FROM repuestos WHERE stock_actual<=stock_minimo AND estado=1) stock_bajo,(SELECT COALESCE(SUM(costo_total),0) FROM ordenes_servicio) costo_total")->fetch();}}

